    public int numDecodings(String s) {
        int next = 1, next2 = 0; // dp[i+1], dp[i+2]
        for (int i = s.length() - 1; i >= 0; i--) {
            int cur = 0;
            if (s.charAt(i) != '0') {
                cur = next;
                if (i + 1 < s.length() && (s.charAt(i) - '0') * 10 + (s.charAt(i + 1) - '0') <= 26) cur += next2;
            }
            next2 = next;
            next = cur;
        }
        return next;
