    def wordBreak(self, s: str, wordDict: List[str]) -> bool:
        @cache
        def ok(i: int) -> bool:
            if i == len(s):
                return True
            return any(s.startswith(w, i) and ok(i + len(w)) for w in wordDict)

        return ok(0)
```

**Time:** O(n · w · L): n positions × w words × L to compare
